#include <cstdio>
#include <vector>
#include <algorithm>

int main() {
    int n, C;
    scanf("%d %d", &n, &C);
    std::vector<int> dp(C + 1, 0);
    for (int i = 0; i < n; ++i) {
        int w, v;
        scanf("%d %d", &w, &v);
        for (int c = C; c >= w; --c)
            dp[c] = std::max(dp[c], dp[c - w] + v);
    }
    printf("%d\n", dp[C]);
    return 0;
}
